'use strict';
let pendingFileOperation=null;
const flushBeforeOperations=window.amagoFlush;window.amagoFlush=async()=>{if(pendingFileOperation)await pendingFileOperation;return flushBeforeOperations?.()};
function removeFileMenu(){const menu=$('#file-context-menu');if(menu){const returnTo=menu.returnTo;menu.remove();if(returnTo?.isConnected)returnTo.focus({preventScroll:true})}}
function fileMenuItem(row){if(row.dataset.projectFile)return {project:true,path:row.dataset.projectFile,folder:false};if(row.dataset.projectDir)return {project:true,path:row.dataset.projectDir,folder:true};if(row.dataset.note){const doc=vault.notes.find(d=>d.id===row.dataset.note);return doc?{project:false,path:AmagoLinks.documentPath(doc),id:doc.id,folder:false}:null}if(row.dataset.folder)return {project:false,path:row.dataset.folder,folder:true};return null}
function showFileMenu(row,x,y){const item=fileMenuItem(row);if(!item)return;removeFileMenu();const menu=document.createElement('div');menu.id='file-context-menu';menu.className='file-context-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Ações de '+item.path);menu.returnTo=row;menu.innerHTML=`<strong>${esc(item.path.split('/').at(-1))}</strong>${item.folder?`<button role="menuitem" data-file-command="create">${icon('plus')}Nova nota nesta pasta</button>`:''}<button role="menuitem" data-file-command="rename">${icon('edit')}Renomear…</button><button role="menuitem" data-file-command="remove">${icon('trash')}Remover${item.folder?' pasta e conteúdo':''}…</button>`;document.body.append(menu);menu.style.left=Math.max(8,Math.min(x,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button').focus({preventScroll:true});menu.onclick=e=>{const button=e.target.closest('[data-file-command]');if(!button)return;e.preventDefault();e.stopPropagation();removeFileMenu();if(button.dataset.fileCommand==='create'){if(item.project){createProjectItem('markdown');$('#project-name').value=item.path+'/';$('#project-name').focus()}else newNote('',item.path);return}startFileOperation(item,button.dataset.fileCommand).catch(error=>toast(error.message))};menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();removeFileMenu()}}}
const treeSelector='#sidebar [data-project-file],#sidebar [data-project-dir],#sidebar [data-note],#sidebar [data-folder]';
window.addEventListener('contextmenu',e=>{const row=e.target.closest(treeSelector);if(!row)return;e.preventDefault();showFileMenu(row,e.clientX,e.clientY)},true);
window.addEventListener('keydown',e=>{const row=e.target.closest(treeSelector);if(row&&(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')){e.preventDefault();e.stopImmediatePropagation();const rect=row.getBoundingClientRect();showFileMenu(row,rect.left+20,rect.bottom)}},true);
window.addEventListener('pointerdown',e=>{if(!e.target.closest('#file-context-menu'))removeFileMenu()},true);
// Discoverable action button; delegated before explorer navigation.
const actionTree=renderTree;renderTree=function(){actionTree();document.querySelectorAll(treeSelector).forEach(row=>{row.title+=' · botão direito para ações';const more=document.createElement('span');more.className='tree-menu-hint';more.dataset.treeMenu='';more.setAttribute('aria-hidden','true');more.textContent='⋯';row.append(more)});const scroller=$('#sidebar-content');if(scroller)scroller.scrollTop=explorerScroll.get(scroller.dataset.scrollKey)||0};
window.addEventListener('click',e=>{const more=e.target.closest('[data-tree-menu]');if(!more)return;e.preventDefault();e.stopImmediatePropagation();const row=more.closest('.project-entry'),rect=row.getBoundingClientRect();showFileMenu(row,rect.right-40,rect.bottom)},true);
function listAffected(items){return items.length?'<ul class="operation-list">'+items.map(path=>'<li>'+esc(path)+'</li>').join('')+'</ul>':'<p>Nenhuma referência precisa ser alterada.</p>'}
async function startFileOperation(item,action){if(item.project&&!(await saveProjectFile()))return;persist();if(action==='rename'){const original=item.path.split('/').at(-1),value=!item.project&&!item.folder?original.replace(/\.md$/i,''):original;modal(item.folder?'Renomear pasta':'Renomear arquivo',`<form id="rename-item"><label>Novo nome<input id="rename-name" class="field" value="${esc(value)}" required maxlength="160"></label><p>O Âmago verificará os vínculos antes de alterar o nome${item.project&&!item.folder?'. Mantenha a extensão do arquivo':''}.</p><p class="operation-status" role="status"></p><div class="modal-actions"><button type="button" class="plain-button" data-action="close">Cancelar</button><button class="solid-button">Revisar alterações</button></div></form>`);$('#rename-item').onsubmit=async e=>{e.preventDefault();const name=$('#rename-name').value.trim(),button=$('#rename-item button[type="submit"]')||$('.modal-actions .solid-button');button.disabled=true;try{await previewFileOperation(item,action,name)}catch(error){$('.operation-status').textContent=error.message;button.disabled=false}};return}await previewFileOperation(item,action)}
function personalPlan(item,action,name){const docs=vault.notes.map(d=>({...d,path:AmagoLinks.documentPath(d),kind:'markdown'}));const from=item.path;if(!docs.some(d=>AmagoRefactor.inside(d.path,from))&&!vault.folders.includes(from))throw Error('Este item não existe mais.');let to='';if(action==='rename'){AmagoRefactor.validName(name);to=item.folder?name:[...from.split('/').slice(0,-1),name+'.md'].join('/');if(to===from||docs.some(d=>d.path.toLowerCase()===to.toLowerCase())||item.folder&&vault.folders.some(f=>f.toLowerCase()===to.toLowerCase()))throw Error('Esse nome já está em uso.')}const plan=action==='rename'?AmagoRefactor.plan(docs,from,to):{changes:[],referenceCount:0};const references=action==='rename'?plan.changes.map(c=>c.path):docs.filter(d=>!AmagoRefactor.inside(d.path,from)&&AmagoSearch.metadata(d.body).links.some(link=>{const t=resolveLink(docs,d,link);return t&&AmagoRefactor.inside(t.path,from)})).map(d=>d.path);return {...plan,from,to,action,kind:item.folder?'directory':'markdown',files:docs.filter(d=>AmagoRefactor.inside(d.path,from)).map(d=>d.path),references,snapshot:JSON.stringify(vault.notes),folders:JSON.stringify(vault.folders)}}
async function previewFileOperation(item,action,name){const result=item.project?await window.projectAdapter.previewOperation({action,path:item.path,name}):personalPlan(item,action,name);if(result.error)throw Error(result.error);const remove=action==='remove';modal(remove?'Remover '+(item.folder?'pasta e documentos?':'arquivo?'):'Revisar renomeação',`<p><strong>${esc(result.from)}</strong>${remove?' será removido do explorador.':' → <strong>'+esc(result.to)+'</strong>'}</p><p>${remove?`${result.files.length} arquivo(s) afetado(s). ${item.project?'Uma cópia será guardada em .amago/operations, dentro do projeto.':'As notas poderão ser restauradas pela lixeira.'}`:`${result.referenceCount} vínculo(s) será(ão) adaptado(s) em ${result.references.length} documento(s), incluindo caminhos relativos.`}</p>${remove?'<details><summary>Conteúdo afetado</summary>'+listAffected(result.files)+'</details>':''}<h3>${remove?'Documentos que referenciam este conteúdo':'Documentos com links a atualizar'}</h3>${listAffected(result.references)}${remove&&result.references.length?'<p>Esses links deixarão de encontrar seus destinos. O texto das referências será preservado.</p>':''}<p class="operation-status" role="status"></p><div class="modal-actions"><button class="plain-button" data-action="close">Cancelar</button><button class="solid-button" id="apply-file-operation">${remove?'Remover com cópia de recuperação':'Renomear e adaptar links'}</button></div>`);$('#apply-file-operation').onclick=async()=>{const button=$('#apply-file-operation');button.disabled=true;window.amagoOperationBusy=true;document.body.classList.add('operation-busy');$('.operation-status').textContent='Aplicando alterações…';pendingFileOperation=applyFileOperation(item,result);try{const applied=await pendingFileOperation;closeModal();if(item.project)modal('Operação concluída',`<p>${remove?'O conteúdo foi removido do explorador.':'O item foi renomeado e seus vínculos foram atualizados.'}</p><p>A cópia anterior está em:</p><code class="operation-status">${esc(applied.backup)}/original</code><p>Para recuperar, copie os arquivos dessa pasta de volta aos caminhos originais. O arquivo manifest.json registra a operação.</p><div class="modal-actions"><button class="solid-button" data-action="close">Concluir</button></div>`);else toast('Alterações aplicadas.')}catch(error){$('.operation-status').textContent=error.message;button.textContent='Reabrir prévia';button.disabled=false;button.onclick=()=>startFileOperation(item,action).catch(error=>toast(error.message))}finally{pendingFileOperation=null;window.amagoOperationBusy=false;document.body.classList.remove('operation-busy')}}}
async function applyFileOperation(item,plan){if(!item.project){if(plan.snapshot!==JSON.stringify(vault.notes)||plan.folders!==JSON.stringify(vault.folders))throw Error('As notas mudaram. Revise a operação novamente.');const selected=vault.notes.filter(d=>AmagoRefactor.inside(AmagoLinks.documentPath(d),plan.from));if(plan.action==='rename'){for(const change of plan.changes){const doc=vault.notes.find(d=>AmagoLinks.documentPath(d)===change.path);doc.body=change.body;doc.updated=stamp()}if(item.folder){vault.folders=vault.folders.map(f=>AmagoRefactor.mapPath(f,plan.from,plan.to));for(const d of selected)d.folder=AmagoRefactor.mapPath(d.folder,plan.from,plan.to);state.openFolders.add(plan.to)}else selected[0].title=plan.to.split('/').at(-1).replace(/\.md$/i,'')}else{for(const d of selected)vault.trash.push({...structuredClone(d),deletedAt:stamp()});const ids=new Set(selected.map(d=>d.id));vault.notes=vault.notes.filter(d=>!ids.has(d.id));state.tabs=state.tabs.filter(id=>!ids.has(id));studio.panes=studio.panes.filter(p=>p.source!=='vault'||!ids.has(p.id));if(item.folder)vault.folders=vault.folders.filter(f=>!AmagoRefactor.inside(f,plan.from));if(!vault.folders.length)vault.folders.push('Notas');if(!vault.notes.length)vault.notes.push({id:uid(),title:'Novo começo',folder:vault.folders[0],tags:[],body:'',favorite:false,created:stamp(),updated:stamp()});state.id=vault.notes[0]?.id;state.view='home'}persist();render();return {done:true}}
 const result=await window.projectAdapter.applyOperation(plan.id);if(result.error)throw Error(result.error);const map=p=>plan.action==='rename'?AmagoRefactor.mapPath(p,plan.from,plan.to):AmagoRefactor.inside(p,plan.from)?null:p,current=workbench.file?.path,next=current?map(current):null;
 const previousActive=studio.active;workbench.tabs=workbench.tabs.map(map).filter(Boolean);studio.panes=studio.panes.map(p=>p.source==='project'?{...p,id:map(p.id)}:p).filter(p=>p.id);workbench.expanded=new Set([...workbench.expanded].map(map).filter(Boolean));const retainedPanes=studio.panes;const prefs=graphPreferences();prefs.positions=Object.fromEntries(Object.entries(prefs.positions).map(([key,value])=>[map(key),value]).filter(([key])=>key));discovery.selected=discovery.selected?map(discovery.selected):null;discovery.localFocus=discovery.localFocus?map(discovery.localFocus):null;persist();studio.files.clear();workbench.file=null;studio.panes=[];studio.active=0;clearProjectImages();state.view='project-home';await refreshProject();if(discovery.indexPromise)await discovery.indexPromise;const active=next||retainedPanes[0]?.id;if(active)await openProjectFile(active);if(retainedPanes.length>1){for(const pane of retainedPanes){const doc=discovery.docs.find(d=>d.path===pane.id);if(doc&&AmagoFiles.editable(doc))studio.files.set(pane.id,{...doc,savedBody:doc.body,dirty:false})}studio.panes=retainedPanes.filter(p=>studio.files.has(p.id));studio.active=Math.min(previousActive,studio.panes.length-1);if(studio.panes[studio.active])workbench.file=studio.files.get(studio.panes[studio.active].id)}render();return result;
}
